<?php $stats=row('SELECT COUNT(*) AS total,COUNT(DISTINCT domain) AS domains,SUM(status="lost") AS lost,SUM(follow="follow") AS followed,SUM(follow="nofollow") AS nofollow,SUM(first_seen>=DATE_SUB(CURDATE(),INTERVAL 30 DAY)) AS recent FROM backlinks WHERE website_id=?',[$wid]);?><div class="grid grid-3 stack"><?php foreach(['total'=>'Total backlinks','domains'=>'Referring domains','recent'=>'New in 30 days','lost'=>'Lost backlinks','followed'=>'Follow links','nofollow'=>'Nofollow links'] as $key=>$label):?><div class="card metric"><span class="metric-label"><?=e($label)?></span><div class="metric-value"><?=number_format((int)$stats[$key])?></div></div><?php endforeach;?></div>
